Q: How to decode mp3 into wav using lame in C/C++? A: <p>Unfortunately, <code>lame_decode_...()</code> have been deprecated and obsolescent and are not available in Debian and probably others. You how have to use the <code>hip_decode_...()</code> interface, of which there is an almost-complete example in <a href="https://stackoverflow.com/questions/66702481">How to decode using lame (mp3-&gt;wav) in c++</a> which I've un-windows-ified all except for providing a <code>main()</code> routing to call <code>Decode()</code> with two file names so if you can provide that it might work.</p>
<p>LameHelper.h:</p>
<pre><code>// Source - https://stackoverflow.com/q/66702481
// Posted by Jungwon, modified by community.
// Retrieved 2026-01-31, License - CC BY-SA 4.0

#pragma once
#ifndef _LAME_HELPER_H_
#define _LAME_HELPER_H_

// #include &lt;windows.h&gt;
#include &lt;lame/lame.h&gt;

#define LH_STARTED WM_USER+1
#define LH_COMPUTED WM_USER+2
#define LH_DONE WM_USER+3
#define LH_ERROR WM_USER+4

#define MAX_THREAD_COUNT 5

enum encode_mode_e
{
    EM_ABR,
    EM_CBR,
    EM_VBR
};

enum encode_channel_e
{
    EC_MONO,
    EC_STEREO
};

enum bitrate_e
{
    BR_8kbps = 8,
    BR_16kbps = 16,
    BR_24kbps = 24,
    BR_32kbps = 32,
    BR_40kbps = 40,
    BR_48kbps = 48,
    BR_56kbps = 56,
    BR_64kbps = 64,
    BR_80kbps = 80,
    BR_96kbps = 96,
    BR_112kbps = 112,
    BR_128kbps = 128,
    BR_144kbps = 144,
    BR_160kbps = 160,
    BR_192kbps = 192,
    BR_224kbps = 224,
    BR_256kbps = 256,
    BR_320kbps = 320
};

enum samplerate_e
{
    SR_8khz = 8000,
    SR_11khz = 11025,
    SR_12khz = 12000,
    SR_16khz = 16000,
    SR_22khz = 22050,
    SR_24khz = 24000,
    SR_32khz = 32000,
    SR_44khz = 44100,
    SR_48khz = 48000
};

struct settings_t
{
    char* title;
    char* artist;
    char* album;
    char* comment;
    char* year;
    char* track;
    char* genre;
    char* albumart;

    encode_channel_e channels;
    bitrate_e abr_bitrate;
    bitrate_e cbr_bitrate;
    int quality;
    encode_mode_e enc_mode;
    samplerate_e resample_frequency;
    samplerate_e in_samplerate;

    //The constructor; used to set default values
    settings_t();
};

class CLameHelper; //lameHelper prototype, needed because of struct StaticParam_t

//Use to hold parameters for the thread function
struct StaticParam_t
{
    char* pcm;
    char* mp3;
    settings_t settings;
    CLameHelper* lhObj;
};


class CLameHelper
{
public :
    static const int PCM_SIZE = 4096;
    static const int MP3_SIZE = 4096;

    static int Decode_s(void* pParam);

    void WriteWaveHeader(FILE* const, int, int, int, int);
    void Write32BitLowHigh(FILE*, int);
    void Write16BitLowHigh(FILE*, int);

    int SetID3AlbumArt(lame_t gfp, char const* szFileName);
    void errorHandler(char*);
    char errMsg[1000];

public:
    CLameHelper();
    ~CLameHelper();

    int Decode(char* szMp3_in, char* szPcm_out);
};

#endif
</code></pre>
<p>Decode.cpp:</p>
<pre><code>// Source - https://stackoverflow.com/q/66702481
// Posted by Jungwon, modified by community.
// Retrieved 2026-01-31, License - CC BY-SA 4.0

#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &quot;LameHelper.h&quot;

settings_t::settings_t()
{
    //Setting the default values
    title = &quot;&quot;;
    artist = &quot;&quot;;
    album = &quot;&quot;;
    comment = &quot;&quot;;
    year = &quot;&quot;;
    track = &quot;&quot;;
    genre = &quot;&quot;;
    albumart = NULL;

    channels = EC_STEREO;
    abr_bitrate = BR_128kbps;
    cbr_bitrate = BR_128kbps;
    quality = 5;
    enc_mode = EM_CBR;
    resample_frequency = SR_44khz; 
    in_samplerate = SR_44khz;
}


CLameHelper::CLameHelper()
{
}

CLameHelper::~CLameHelper()
{
}


int CLameHelper::SetID3AlbumArt(lame_t gfp, char const* szFileName)
{
    int iResult = -1;
    FILE *pFileName = 0;
    char *szAlbumart = 0;

    if(szFileName == NULL) 
    {
        return 0;
    }

    pFileName = fopen(szFileName, &quot;rb&quot;);

    if(!pFileName) 
    {
        iResult = 1;
    }
    else
    {
        size_t size;

        fseek(pFileName, 0, SEEK_END);
        size = ftell(pFileName);
        fseek(pFileName, 0, SEEK_SET);
        szAlbumart = (char*)malloc(size);
        if(!szAlbumart)
        {
            iResult = 2;            
        }
        else 
        {
            if(fread(szAlbumart, 1, size, pFileName) != size)
            {
                iResult = 3;
            }
            else 
            {
                iResult = (gfp, szAlbumart, size) ? 4 : 0;
            }
            free(szAlbumart);
        }
        fclose(pFileName);
    }
    switch(iResult)
    {
    case 1:
        sprintf(errMsg, &quot;WARNING: could not find file '%s' for szAlbumart.\n&quot;, szFileName);
        errorHandler(errMsg); 
        break;
    case 2:
        errorHandler(&quot;WARNING: insufficient memory for reading the szAlbumart.\n&quot;);
        break;
    case 3:
        sprintf(errMsg, &quot;WARNING: read error in '%s' for szAlbumart.\n&quot;, szFileName);
        errorHandler(errMsg);
        break;
    case 4: 
        sprintf(errMsg, &quot;WARNING: unsupported image: '%s' for szAlbumart. Specify JPEG/PNG/GIF image\n&quot;, szFileName);
        errorHandler(errMsg);
        break;
    default: 
        break;
    }
    return iResult;
}


void CLameHelper::Write16BitLowHigh(FILE * fp, int val)
{
    unsigned char bytes[2];
    bytes[0] = (val &amp; 0xff);
    bytes[1] = ((val &gt;&gt; 8) &amp; 0xff);
    fwrite(bytes, 1, 2, fp);
}

void CLameHelper::Write32BitLowHigh(FILE * fp, int val)
{
    unsigned char bytes[4];
    bytes[0] = (val &amp; 0xff);
    bytes[1] = ((val &gt;&gt; 8) &amp; 0xff);
    bytes[2] = ((val &gt;&gt; 16) &amp; 0xff);
    bytes[3] = ((val &gt;&gt; 24) &amp; 0xff);
    fwrite(bytes, 1, 4, fp);
}

void CLameHelper::WriteWaveHeader(FILE * const fp, int pcmbytes, int freq, int channels, int bits)
{
    int     bytes = (bits + 7) / 8;
    /* quick and dirty, but documented */
    fwrite(&quot;RIFF&quot;, 1, 4, fp); /* label */
    Write32BitLowHigh(fp, pcmbytes + 44 - 8); /* length in bytes without header */
    fwrite(&quot;WAVEfmt &quot;, 2, 4, fp); /* 2 labels */
    Write32BitLowHigh(fp, 2 + 2 + 4 + 4 + 2 + 2); /* length of PCM format declaration area */
    Write16BitLowHigh(fp, 1); /* is PCM? */
    Write16BitLowHigh(fp, channels); /* number of channels */
    Write32BitLowHigh(fp, freq); /* sample frequency in [Hz] */
    Write32BitLowHigh(fp, freq * channels * bytes); /* bytes per second */
    Write16BitLowHigh(fp, channels * bytes); /* bytes per sample time */
    Write16BitLowHigh(fp, bits); /* bits per sample */
    fwrite(&quot;data&quot;, 1, 4, fp); /* label */
    Write32BitLowHigh(fp, pcmbytes); /* length in bytes of raw PCM data */
}

//the static function used for the thread
int CLameHelper::Decode_s(void* param)
{
    StaticParam_t* sp = (StaticParam_t*)param;
    char* szPcm_out = sp-&gt;pcm;
    char* szMp3_in = sp-&gt;mp3;

    CLameHelper* lh = (CLameHelper*)sp-&gt;lhObj;
    return lh-&gt;Decode(szMp3_in, szPcm_out);
}


int CLameHelper::Decode(char* szMp3_in, char* szPcm_out)
{
    int read, i, samples;
    long wavsize = 0; // use to count the number of mp3 byte read, this is used to write the length of the wave file
    long cumulative_read = 0;

    short int pcm_l[PCM_SIZE], pcm_r[PCM_SIZE];
    unsigned char mp3_buffer[MP3_SIZE];

    FILE* mp3 = fopen(szMp3_in, &quot;rb&quot;);
    if(mp3 == NULL)
    {
        sprintf(errMsg, &quot;FATAL ERROR: file '%s' can't be open for read. Aborting!\n&quot;, szMp3_in);
        errorHandler(errMsg);
        return -1;
    }
    fseek(mp3, 0, SEEK_END);
    long MP3_total_size = ftell(mp3);
    fseek(mp3, 0, SEEK_SET);


    FILE* pcm = fopen(szPcm_out, &quot;wb&quot;);
    if(pcm == NULL)
    {
        sprintf(errMsg, &quot;FATAL ERROR: file '%s' can't be open for write. Aborting!\n&quot;, szPcm_out);
        errorHandler(errMsg);
        return -1;
    }


    lame_t lame = lame_init();
    lame_set_decode_only(lame, 1);
    if(lame_init_params(lame) == -1)
    {
        sprintf(errMsg, &quot;FATAL ERROR: parameters failed to initialize properly in lame. Aborting!\n&quot;, szPcm_out);
        errorHandler(errMsg);
        return -2;
    }

    hip_t hip = hip_decode_init();

    mp3data_struct mp3data;
    memset(&amp;mp3data, 0, sizeof(mp3data));

    int nChannels = -1;
    int nSampleRate = -1;
    int mp3_len;


    while((read = fread(mp3_buffer, sizeof(char), MP3_SIZE, mp3)) &gt; 0)
    {
        mp3_len = read;
        cumulative_read += read * sizeof(char);
        do
        {
            samples = hip_decode1_headers(hip, mp3_buffer, mp3_len, pcm_l, pcm_r, &amp;mp3data);
            wavsize += samples;

            if(mp3data.header_parsed == 1)//header is gotten
            {
                if(nChannels &lt; 0)//reading for the first time
                {
                    //Write the header
                    WriteWaveHeader(pcm, 0x7FFFFFFF, mp3data.samplerate, mp3data.stereo, 16); //unknown size, so write maximum 32 bit signed value
                }
                nChannels = mp3data.stereo;
                nSampleRate = mp3data.samplerate;
            }

            if(samples &gt; 0 &amp;&amp; mp3data.header_parsed != 1)
            {
                errorHandler(&quot;WARNING: lame decode error occured!&quot;);
                break;
            }

            if(samples &gt; 0)
            {
                for(i = 0 ; i &lt; samples; i++)
                {
                    fwrite((char*)&amp;pcm_l[i], sizeof(char), sizeof(pcm_l[i]), pcm);
                    if(nChannels == 2)
                    {
                        fwrite((char*)&amp;pcm_r[i], sizeof(char), sizeof(pcm_r[i]), pcm);
                    }
                }
            }
            mp3_len = 0;
        } while(samples&gt;0);
    }

    i = (16 / 8) * mp3data.stereo;
    if (wavsize &lt;= 0) 
    {
       wavsize = 0;
    }
    else if (wavsize &gt; 0xFFFFFFD0 / i) 
    {
        wavsize = 0xFFFFFFD0;
    }
    else 
    {
        wavsize *= i;
    }

    if(!fseek(pcm, 0l, SEEK_SET))//seek back and adjust length
        WriteWaveHeader(pcm, (int) wavsize, mp3data.samplerate, mp3data.stereo, 16);
    else
        errorHandler(&quot;WARNING: can't seek back to adjust length in wave header!&quot;);

    hip_decode_exit(hip);
    lame_close(lame);
    fclose(mp3);
    fclose(pcm);

    return 0;
}

void CLameHelper::errorHandler(char* msg)
{
    printf(&quot;%s\n&quot;, msg);
}

int main(int argc, char **argv)
{
    if (argc != 3) return 1;
    // Decode(argv[1], argv[2]);
    return 0;
}
</code></pre>

Q: JS snippet works in browser console but not in selenium A: <p>The issue is that <code>FrecencyUserSettings.loadIfNecessary()</code> is <strong>asynchronous</strong> - it returns a Promise that needs to resolve before the data is available. In the browser console, you're entering commands manually with time between them, so the data loads before you call <code>getCurrentValue()</code>. In Selenium, all the code executes immediately without waiting.</p>
<h2>Solution</h2>
<p>You need to wait for the Promise to resolve. Here's the fixed JavaScript:</p>
<p>javascript</p>
<pre><code>window.FrecencyUserSettings ??= webpackChunkdiscord_app.push([[Symbol()],,e=&gt;Object.values(e.c).values().map(m=&gt;m.exports).filter(x=&gt;typeof x==&quot;object&quot;&amp;&amp;x!=window&amp;&amp;x!=DOMTokenList.prototype).flatMap(x=&gt;[x,...Object.values(x)]).find(x=&gt;!x?.$$loader&amp;&amp;x?.ProtoClass?.typeName?.endsWith(&quot;.FrecencyUserSettings&quot;))]);

function downloadJSON(content, download) {
  const json = JSON.stringify(content, null, 2);
  Object.assign(document.createElement(&quot;a&quot;), {
    href: URL.createObjectURL(new Blob([json], { type: &quot;application/json&quot; })),
    download
  }).click();
}


FrecencyUserSettings.loadIfNecessary().then(() =&gt; {
  downloadJSON(FrecencyUserSettings.getCurrentValue().favoriteGifs.gifs, &quot;discord-favorite-gifs.json&quot;);
});
</code></pre>
<p>The key change is wrapping the <code>downloadJSON</code> call in a <code>.then()</code> callback that executes after the Promise resolves.</p>

Q: API Key Required message in QML MapView even with valid key A: <p>In the Qt <a href="https://doc.qt.io/qt-6/location-plugin-osm.html" rel="nofollow noreferrer">documentation</a> I can't find <code>osm.mapping.custom.query_parameters</code>, but in <code>osm.mapping.custom.host</code> it says:</p>
<blockquote>
<p>The url string of a custom tile server. This parameter should be set to a valid server url offering the correct OSM API. The postfix &quot;%z/%x/%y.png&quot; will be added to the url. Since 6.5 the postfix will not be added if the url ends with &quot;.png&quot;. <strong>If the server requires an apikey, it has to be added to the url string.</strong></p>
</blockquote>
<p>This bugreport <a href="https://qt-project.atlassian.net/browse/QTBUG-115742" rel="nofollow noreferrer">QTBUG-115742</a> provides the following snippet:</p>
<pre><code>PluginParameter {
    name: &quot;osm.mapping.custom.host&quot;;
    value: &quot;https://tile.thunderforest.com/cycle/%z/%x/%y.png?apikey=&lt;my key&gt;&quot;
}
</code></pre>
<p>Also this <a href="https://qt-project.atlassian.net/browse/QTBUG-115742?focusedCommentId=2579562" rel="nofollow noreferrer">comment</a></p>
<pre><code>&quot;https://tile.thunderforest.com/cycle/%z/%x/%y.png?apikey=&lt;API_KEY&gt;&amp;&quot;
</code></pre>
<hr />
<p>I've written a small test application and found out that it is important to set <code>activeMapType</code> as stated in</p>
<blockquote>
<p>To use this server, the Map::activeMapType parameter of the Map should be set to the supported map type whose type is MapType.CustomMap. This map type is only be available if this plugin parameter is set, in which case it is always Map::supportedMapTypes[supportedMapTypes.length - 1].</p>
</blockquote>
<p>Unfortunately it wasn't able to dynamically change the style. It needs the <code>clearData()</code> call, otherwise after restart it will show the previous selected style.</p>
<pre><code>import QtQuick
import QtLocation
import QtPositioning

Window {
    id: root
    width: 640
    height: 480
    visible: true
    title: qsTr(&quot;Hello World&quot;)

    // &quot;cycle&quot;,
    // &quot;transport&quot;,
    // &quot;landscape&quot;,
    // &quot;outdoors&quot;,
    // &quot;transport-dark&quot;,
    // &quot;spinal-map&quot;,
    // &quot;pioneer&quot;,
    // &quot;mobile-atlas&quot;,
    // &quot;neighbourhood&quot;,
    // &quot;atlas&quot;

    property string style: &quot;landscape&quot;
    property string apiKey: &quot;&lt;API_KEY&gt;&quot;

    MapView {
        id: mapView

        anchors.fill: parent

        map {
            plugin: Plugin {
                name: &quot;osm&quot;

                PluginParameter {
                    name: &quot;osm.mapping.custom.host&quot;
                    value: `https://tile.thunderforest.com/${root.style}/%z/%x/%y.png?apikey=${root.apiKey}`
                }
            }

            center: QtPositioning.coordinate(45.4642, 9.1900)
            zoomLevel: 14

            activeMapType: mapView.map.supportedMapTypes[mapView.map.supportedMapTypes.length - 1]
        }
    }

    // Reset is needed
    Component.onCompleted: mapView.map.clearData()
}
</code></pre>
